package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

var WsEofFlag string         // PIC X len=1 = "N"
var WsDiscount decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal     // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal // PIC 9(8)V99 len=10 = 0
var WsCount int64             // PIC 9(3) len=3 = 0
var WsPriceEd string          // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string           // PIC ZZ,ZZ9.99 len=9
var WsNetEd string            // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string          // PIC ZZ,ZZZ,ZZ9.99 len=13

var discFile *os.File
var discReader *bufio.Scanner
var discRec DiscRec
var discAtEnd bool

func formatEdited(v decimal.Decimal, picture string) string {
	// count integer and decimal digit placeholders
	dotIdx := strings.Index(picture, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		decPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		decPic = ""
	}
	nInt := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			nInt++
		}
	}
	nDec := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			nDec++
		}
	}

	// prepare scaled integer for extracting digits
	// v is assumed to have at most nDec decimals; truncation/round already done before
	neg := v.IsNegative()
	if neg {
		v = v.Abs()
	}
	// shift to get scaled value
	scaled := v.Shift(int32(nDec))
	// truncate toward zero to integer
	scaled = scaled.Truncate(0)
	// integer part = scaled / 10^nDec
	pow10Dec := decimal.New(1, int32(nDec))
	var intPart decimal.Decimal
	if nDec > 0 {
		intPart = scaled.Div(pow10Dec).Truncate(0)
	} else {
		intPart = scaled
	}
	// fractional part
	var fracPart decimal.Decimal
	if nDec > 0 {
		fracPart = scaled.Sub(intPart.Mul(pow10Dec))
		if fracPart.IsNegative() {
			fracPart = fracPart.Abs()
		}
	}

	// handle high-order truncation for integer part
	// intPartMod = intPart % 10^nInt
	var intPartMod int64
	// compute 10^nInt as int64 (nInt <= 8, fits)
	var modVal int64 = 1
	for i := 0; i < nInt; i++ {
		modVal *= 10
	}
	// intPart may be up to 10^8 fits int64
	ipInt := intPart.IntPart() // decimal to int64
	intPartMod = ipInt % modVal

	// build digit string for integer part padded to nInt
	intDigits := fmt.Sprintf("%0*d", nInt, intPartMod)

	// fractional digits string padded to nDec
	fracDigits := ""
	if nDec > 0 {
		fpInt := fracPart.IntPart()
		fracDigits = fmt.Sprintf("%0*d", nDec, fpInt)
	}

	// format integer picture
	outInt := make([]rune, 0, len(intPic))
	digitIdx := 0
	suppress := true
	for _, ch := range intPic {
		switch ch {
		case ',':
			if suppress {
				outInt = append(outInt, ' ')
			} else {
				outInt = append(outInt, ',')
			}
		case 'Z':
			d := intDigits[digitIdx]
			digitIdx++
			if suppress {
				if d != '0' {
					suppress = false
					outInt = append(outInt, rune(d))
				} else {
					outInt = append(outInt, ' ')
					// remain suppress
				}
			} else {
				outInt = append(outInt, rune(d))
			}
		case '9':
			d := intDigits[digitIdx]
			digitIdx++
			outInt = append(outInt, rune(d))
			suppress = false
		default:
			outInt = append(outInt, ch)
		}
	}

	// assemble final
	var sb strings.Builder
	for _, r := range outInt {
		sb.WriteRune(r)
	}
	if dotIdx >= 0 {
		sb.WriteRune('.')
		sb.WriteString(fracDigits)
		// if picture had extra chars after decimal beyond Z/9 (unlikely)
		// handle any commas/dots in decPic : but decPic is only 9s
	}
	result := sb.String()
	// ensure length equals picture length (picture includes dot)
	// result already equals len(picture) for our pictures
	_ = neg
	return result
}

func formatUneditedInt(v int64, digits int) string {
	return fmt.Sprintf("%0*d", digits, v)
}

func parsePic9V99(s string, scale int32) decimal.Decimal {
	s = strings.TrimSpace(s)
	if s == "" {
		return decimal.Zero
	}
	// s should be digits only
	var n int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return decimal.New(n, -scale)
}

func parsePic9(s string) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	var n int64
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			n = n*10 + int64(ch-'0')
		}
	}
	return n
}

func mainPara() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer discFile.Close()

	// Use scanner that keeps spaces; bufio.Scanner by default strips newline and keeps content
	// Need to handle lines that may be shorter than 15 - pad
	// Use bufio.Reader to get raw lines preserving trailing spaces? input.dat is LINE SEQUENTIAL
	// trailing spaces before newline are significant but often trimmed by editor.
	// However record is 15 bytes: if line shorter, pad with spaces.
	// Scanner will return line without newline and will trim? It returns content without newline, but keeps other spaces except it strips \r.
	// Leading/trailing spaces are kept (Scanner does not trim).
	discReader = bufio.NewScanner(discFile)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	discReader.Buffer(buf, 10*1024*1024)

	// Initialize working storage defaults
	WsEofFlag = "N"
	WsDiscount = decimal.Zero
	WsNet = decimal.Zero
	WsTotalNet = decimal.Zero
	WsCount = 0
	discAtEnd = false

	readPara()
	for !discAtEnd {
		processPara()
	}
	// CLOSE
	// scanner will be done
	summaryPara()
}

func readPara() {
	if !discReader.Scan() {
		// check error
		if err := discReader.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		discAtEnd = true
		WsEofFlag = "Y"
		return
	}
	line := discReader.Text()
	// Scanner strips trailing \r; keep as is
	// Pad/truncate to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse fields at offsets
	drItem := line[0:6]
	drPriceStr := line[6:13]
	drPctStr := line[13:15]

	discRec.DrItem = drItem
	discRec.DrPrice = parsePic9V99(drPriceStr, 2)
	discRec.DrPct = parsePic9(drPctStr)
}

func processPara() {
	// COMPUTE WS-DISCOUNT ROUNDED = DR-PRICE * DR-PCT / 100
	mul := discRec.DrPrice.Mul(decimal.New(discRec.DrPct, 0))
	div := mul.Shift(-2)
	// store with overflow truncation then round: compute then round to 2
	rounded := div.Round(2)
	// truncation simulation for overflow of 9(5)V99 is not needed for test but apply low-order truncation if needed
	// Capacity 5 integer digits = 7 total digits scaled at 2 decimals -> max scaled = 9999999 (9(5)V99 => 99999.99)
	// If overflow, keep low-order digits: scaled % 10^7 ?
	// Apply generic truncation to fit field: keep low-order digits that fit
	WsDiscount = truncateToField(rounded, 5, 2)

	// COMPUTE WS-NET = DR-PRICE - WS-DISCOUNT
	net := discRec.DrPrice.Sub(WsDiscount)
	WsNet = truncateToField(net, 5, 2)

	// ADD WS-NET TO WS-TOTAL-NET
	WsTotalNet = WsTotalNet.Add(WsNet)
	// overflow for total 9(8)V99 handled similarly if needed
	WsTotalNet = truncateToField(WsTotalNet, 8, 2)

	WsCount++
	// apply truncation for count 9(3) low-order
	WsCount = WsCount % 1000

	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")

	// DISPLAY
	// DR-PCT zero-padded to 2
	pctStr := formatUneditedInt(discRec.DrPct, 2)
	// DISPLAY concatenates
	fmt.Printf("%s %s %s%% %s %s\n", discRec.DrItem, WsPriceEd, pctStr, WsDiscEd, WsNetEd)

	readPara()
}

func truncateToField(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// Keep only low-order digits that fit: total digits = intDigits + scale
	totalDigits := intDigits + int(scale)
	// scaled integer = v * 10^scale
	scaled := v.Shift(int32(scale)).Truncate(0)
	// mod = 10^totalDigits
	mod := decimal.New(1, int32(totalDigits))
	// For negative values, COBOL keeps sign? Not needed here positive only
	// low-order digits: scaled % mod (preserving sign)
	// Use IntPart may overflow for large mod but our sizes are small (max 10 digits)
	// Use decimal Mod via manual
	rem := scaled.Mod(mod)
	// decimal.Mod may keep sign of dividend
	// reconstruct value = rem / 10^scale
	return rem.Shift(-scale)
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	fmt.Printf("ITEMS: %s NET TOTAL: %s\n", countStr, WsTotalEd)
}

func main() {
	mainPara()
}
